export const SOLUTION_STRATEGIES_ACTIVITIES = [
{n:1,type:"mcq",micro:"Apa itu strategi",q:"Dalam memecahkan masalah, 'strategi' berarti...",options:["Rencana umum tentang CARA kamu akan mendekati dan menyelesaikan masalah","Nama lain untuk masalah itu sendiri, yaitu keadaan yang sedang ingin kamu ubah","Menebak jawaban secepat mungkin tanpa berpikir panjang supaya cepat selesai"],answer:0,explain:"Strategi adalah pendekatan keseluruhan — misalnya 'coba contoh kecil dulu' atau 'kerjakan mundur dari tujuan'.",hint:"Strategi menjawab 'bagaimana caraku menyerang masalah ini?'"},
{n:2,type:"mcq",micro:"Rencana vs melakukan",q:"'Rencana' berbeda dari 'strategi' karena rencana biasanya berisi...",options:["Daftar nama murid di kelas beserta nomor absen dan tanggal lahirnya","Langkah-langkah nyata yang berurutan, siapa melakukan apa, dan kapan","Hanya perasaan tentang masalah itu, misalnya senang, kesal, atau bingung"],answer:1,explain:"Strategi adalah pendekatan; rencana adalah langkah konkret untuk menjalankan pendekatan itu.",hint:"Rencana lebih rinci: langkah 1, langkah 2, langkah 3."},
{n:3,type:"mcq",micro:"Mengapa merencanakan",q:"Membuat rencana sebelum bertindak membantu karena...",options:["Membuat pekerjaan menjadi lebih lama, padahal hasil akhirnya tetap tidak berubah","Membuat masalah terlihat resmi dan penting, sehingga orang lain segan bertanya, walau tak membantu","Mengurangi langkah yang terlupakan, pekerjaan ulang, dan kebingungan di tengah jalan"],answer:2,explain:"Rencana memberi arah. Tanpa rencana, kita mudah tersesat, mengulang, atau melewatkan bagian penting.",hint:"Apa yang terjadi kalau kamu mulai memasak tanpa tahu resepnya?"},
{n:4,type:"mcq",micro:"Empat langkah Polya",q:"Salah satu kerangka klasik memecahkan masalah punya empat langkah: (1) memahami masalah, (2) menyusun rencana, (3) melaksanakan rencana, (4) memeriksa hasil. Langkah yang paling sering dilewati orang adalah...",options:["Langkah 1 dan 4 (memahami dan memeriksa)","Langkah 3 (melaksanakan rencana)","Langkah 2 dan 3 (rencana dan pelaksanaan)"],answer:0,explain:"Banyak orang langsung melompat ke 'mengerjakan' tanpa benar-benar memahami masalah, dan berhenti begitu ada jawaban tanpa memeriksanya.",hint:"Langkah mana yang terasa 'tidak seru' sehingga sering dilewati?"},
{n:5,type:"order",micro:"Empat langkah memecahkan masalah",q:"Urutkan empat langkah umum memecahkan masalah.",items:["Pahami masalahnya: apa yang diketahui, apa yang dicari","Susun rencana: pilih strategi dan langkah-langkahnya","Laksanakan rencana langkah demi langkah","Periksa hasil: apakah menjawab masalah dan masuk akal"],answer:[0,1,2,3],explain:"Pahami → rencanakan → laksanakan → periksa. Kalau macet di satu langkah, sering perlu kembali ke langkah sebelumnya.",hint:"Kamu tidak bisa merencanakan sebelum memahami."},
{n:6,type:"mcq",micro:"Memahami masalah dulu",q:"'Memahami masalah' antara lain berarti bisa menjawab...",options:["'Berapa lama waktu istirahat dan jam berapa bel pulang berbunyi?'","'Apa yang diketahui? Apa yang ditanyakan? Apa batasannya?'","'Siapa penulis soal ini dan di penerbit mana bukunya dicetak?'"],answer:1,explain:"Sebelum merencanakan, pastikan kamu tahu titik awal (yang diketahui), titik tujuan (yang dicari), dan aturan mainnya (batasan).",hint:"Tiga pertanyaan: tahu apa, cari apa, batas apa."},
{n:7,type:"mcq",micro:"Strategi: coba contoh kecil",q:"Untuk masalah 'berapa banyak jabat tangan kalau 30 orang saling berjabat tangan sekali', strategi awal yang baik:",options:["Menyerah saja, karena masalah sebesar itu terlalu sulit dihitung","Langsung mengalikan 30 x 30 lalu menjadikannya jawaban akhir","Coba dulu dengan 2, 3, lalu 4 orang, cari polanya, baru terapkan ke 30"],answer:2,explain:"Menyederhanakan ke kasus kecil lalu mencari pola adalah strategi kuat untuk masalah yang tampak besar.",hint:"Kalau 30 terlalu banyak, coba angka kecil dulu."},
{n:8,type:"mcq",micro:"Strategi: gambar diagram",q:"Untuk soal 'Rita berdiri di antara Budi dan Ani; Ani di paling kiri; siapa di tengah?', strategi yang membantu:",options:["Menggambar posisi mereka dalam garis","Menghitung jumlah huruf di nama mereka bertiga","Menghafal semua nama"],answer:0,explain:"Menggambar diagram atau sketsa mengubah informasi kata menjadi gambar yang mudah dibaca.",hint:"Bisakah kamu menaruh ketiga orang itu di sebuah garis?"},
{n:9,type:"mcq",micro:"Strategi: buat daftar teratur",q:"Untuk 'sebutkan semua bilangan 2 angka yang jumlah angkanya 5', strategi yang mencegah ada yang terlewat:",options:["Menebak beberapa bilangan saja lalu berhenti","Membuat daftar teratur: 14, 23, 32, 41, 50","Menjawab 'banyak' tanpa menyebut bilangannya"],answer:1,explain:"Daftar yang disusun sistematis (misalnya urut dari angka puluhan terkecil) memastikan tidak ada yang terlewat atau ganda.",hint:"Mulai dari kemungkinan terkecil dan naik satu per satu."},
{n:10,type:"mcq",micro:"Strategi: tebak lalu periksa",q:"Strategi 'tebak lalu periksa' paling berguna ketika...",options:["Tidak ada cara untuk mengecek apakah tebakanmu benar, sehingga hasilnya hanya untung-untungan, dan sulit diperbaiki","Kamu sudah tahu jawaban pastinya sejak awal, sehingga menebak dan memeriksa tidak diperlukan","Kamu punya perkiraan kasar dan bisa cepat mengecek apakah tebakan itu benar, lalu memperbaikinya"],answer:2,explain:"Tebak-periksa-perbaiki berhasil bila mengecek sebuah tebakan itu murah dan hasilnya memberi petunjuk arah perbaikan.",hint:"Strategi ini butuh cara cepat untuk tahu 'terlalu besar' atau 'terlalu kecil'."},
{n:11,type:"tf",micro:"Satu masalah, banyak strategi",q:"Benar atau Salah: Sebuah masalah sering bisa diselesaikan dengan lebih dari satu strategi.",answer:true,explain:"Menggambar diagram, membuat tabel, mencoba kasus kecil, atau bekerja mundur bisa sama-sama membawa ke jawaban. Memilih yang paling cocok adalah bagian dari keterampilan.",hint:"Apakah hanya ada satu jalan menuju satu tempat?"},
{n:12,type:"tf",micro:"Rencana harus super rinci",q:"Benar atau Salah: Rencana yang baik harus selalu merinci setiap detik dan setiap gerakan sebelum kamu boleh mulai.",answer:false,explain:"Rencana cukup rinci untuk memberi arah dan langkah pertama yang jelas. Terlalu banyak detail di awal sering membuang waktu dan cepat usang.",hint:"Apakah kamu perlu merencanakan setiap langkah kaki sebelum berjalan ke dapur?"},
{n:13,type:"mcq",micro:"Langkah pertama yang jelas",q:"Tanda rencana sudah cukup untuk mulai bekerja:",options:["Kamu tahu persis tindakan pertama yang akan kamu lakukan","Rencanamu panjang dan rapi, walau belum tahu mulai dari mana","Banyak yang memuji rencanamu, walau langkah pertama belum jelas"],answer:0,explain:"Rencana yang bisa dijalankan selalu punya 'langkah berikutnya' yang konkret dan jelas.",hint:"Kalau kamu masih bingung 'mulai dari mana', rencananya belum siap."},
{n:14,type:"mcq",micro:"Sumber daya dalam rencana",q:"Selain langkah-langkah, rencana yang baik juga mempertimbangkan...",options:["Cuaca bulan depan dan ramalan hari libur","Waktu, bahan, alat, dan orang yang tersedia","Warna kertas, jenis pena, dan hiasan sampul rencana"],answer:1,explain:"Rencana yang mengabaikan sumber daya (tidak ada waktu, alat, atau orang) akan macet saat dilaksanakan.",hint:"Apa yang kamu butuhkan untuk benar-benar menjalankan tiap langkah?"},
{n:15,type:"mcq",micro:"Rencana cadangan",q:"'Rencana cadangan' berguna untuk...",options:["Diberikan kepada orang lain supaya mereka yang menanggung akibatnya bila rencana utama tidak berjalan","Menghias rencana utama supaya terlihat lebih indah dan lebih meyakinkan ketika dibaca oleh guru","Bagian rencana yang berisiko gagal — supaya kamu tahu apa yang dilakukan bila itu terjadi"],answer:2,explain:"Untuk langkah yang mungkin gagal (hujan saat acara luar ruang, narasumber batal), menyiapkan 'kalau ini gagal, maka...' menghemat panik nanti.",hint:"Apa yang kamu lakukan kalau langkah kunci tidak berjalan?"},
{n:16,type:"mcq",micro:"Melaksanakan sesuai rencana",q:"Saat melaksanakan rencana, kalau satu langkah ternyata lebih sulit dari dugaan, sebaiknya...",options:["Coba sebentar, dan bila tetap macet, kembali ke langkah 'menyusun rencana' untuk menyesuaikan","Lewati semua langkah berikutnya dan kerjakan hanya bagian yang mudah dulu saja","Berhenti total dan menunggu sampai ada orang lain yang datang untuk menolong kamu"],answer:0,explain:"Memecahkan masalah bukan garis lurus. Macet di pelaksanaan sering berarti rencana perlu disesuaikan, bukan dibuang.",hint:"Ke langkah mana kamu kembali kalau rencana tidak jalan?"},
{n:17,type:"mcq",micro:"Memeriksa hasil",q:"Setelah mendapat jawaban, 'memeriksa hasil' berarti...",options:["Langsung menyerahkan jawaban tanpa melihatnya lagi, sebab kamu sudah merasa yakin dan ingin cepat selesai","Bertanya: apakah ini benar-benar menjawab pertanyaannya? Apakah masuk akal? Apakah ada cara lain mengeceknya?","Merayakan jawaban itu bersama teman-teman lalu beralih ke soal berikutnya tanpa mengeceknya kembali, karena merasa sudah cukup"],answer:1,explain:"Pemeriksaan menangkap kesalahan: jawaban yang tidak menjawab pertanyaan, hasil yang mustahil (umur 200 tahun), atau salah hitung.",hint:"Apakah jawaban ini masuk akal untuk dunia nyata?"},
{n:18,type:"mcq",micro:"Perkiraan sebelum menghitung",q:"Membuat perkiraan kasar sebelum menghitung dengan teliti berguna untuk...",options:["Punya pembanding — kalau hasil akhir jauh dari perkiraan, mungkin ada kesalahan","Menggantikan perhitungan teliti, sehingga hasil akhirnya tidak perlu dihitung lagi","Membuat jawaban akhir otomatis benar, asalkan perkiraannya dibulatkan ke puluhan"],answer:0,explain:"Perkiraan berfungsi sebagai 'penjaga': jika 12 × 48 kamu hitung jadi 5.760, perkiraan 12 × 50 = 600 menunjukkan ada yang salah.",hint:"Bagaimana kamu tahu jawabanmu 'kira-kira benar'?"},
{n:19,type:"mcq",micro:"Menuliskan rencana",q:"Menuliskan rencana (bukan hanya menyimpannya di kepala) membantu karena...",options:["Membebaskan pikiran untuk fokus mengerjakan, dan memudahkan berbagi serta meninjau","Membuat tangan cepat pegal sehingga pikiran jadi sulit fokus pada pekerjaan","Tidak ada bedanya, karena yang ditulis dan yang dipikirkan itu sama saja"],answer:0,explain:"Rencana tertulis mengurangi beban ingatan, memudahkan orang lain memahami, dan bisa diperiksa ulang.",hint:"Apa yang lebih mudah dilupakan: rencana di kertas atau rencana di kepala?"},
{n:20,type:"open",micro:"Menyusun rencana sederhana",q:"Kamu punya waktu satu sore untuk membuat kartu ucapan untuk 5 guru. Susun rencana singkat: strategi umum, 4–5 langkah, bahan yang dibutuhkan, dan satu titik yang mungkin macet.",explain:"Rencana baik menyebut strategi (satu desain digandakan), langkah berurutan, bahan, dan antisipasi kendala.",hint:"Pikirkan cara yang menghemat pekerjaan berulang.",sample:"Strategi: buat satu desain, gandakan, lalu personalisasi tiap kartu — lebih cepat daripada mendesain 5 dari nol. Langkah: (1) kumpulkan bahan (kertas tebal, spidol, gunting, hiasan), (2) buat 1 desain dasar, (3) gunting 5 kartu dengan pola sama, (4) tulis pesan berbeda untuk tiap guru, (5) tambah hiasan & periksa nama. Titik macet: kehabisan kertas tebal → cadangan: pakai kertas biasa dilipat dua, atau kurangi hiasan."},
{n:21,type:"classify",micro:"Mencocokkan strategi dengan masalah",q:"Kelompokkan tiap masalah dengan strategi yang paling cocok: 'Gambar diagram', 'Buat tabel/daftar teratur', atau 'Coba kasus kecil lalu cari pola'.",items:["Menentukan posisi duduk 5 anak dari beberapa petunjuk 'di sebelah kiri/kanan'","Menghitung total titik jika pola titik bertambah 3 setiap gambar, sampai gambar ke-50","Mendaftar semua kemungkinan kombinasi baju (3) dan celana (2)"],groups:["Gambar diagram","Coba kasus kecil lalu cari pola","Buat tabel/daftar teratur"],answer:{"Gambar diagram":["Menentukan posisi duduk 5 anak dari beberapa petunjuk 'di sebelah kiri/kanan'"],"Coba kasus kecil lalu cari pola":["Menghitung total titik jika pola titik bertambah 3 setiap gambar, sampai gambar ke-50"],"Buat tabel/daftar teratur":["Mendaftar semua kemungkinan kombinasi baju (3) dan celana (2)"]},explain:"Masalah posisi/hubungan → diagram; masalah pola bertumbuh → kasus kecil; masalah 'sebutkan semua kemungkinan' → daftar teratur.",hint:"Apa bentuk informasi dalam tiap masalah?"},
{n:22,type:"mcq",micro:"Strategi untuk masalah 'sebutkan semua'",q:"Ketika masalah meminta 'semua kemungkinan' atau 'berapa banyak cara', strategi yang mencegah kelewatan:",options:["Menebak angka satu per satu sampai ketemu yang cocok","Membuat daftar atau tabel yang tersusun sistematis","Menjawab dengan perasaan dan firasat pertama yang muncul"],answer:1,explain:"Daftar/tabel sistematis memastikan setiap kemungkinan terhitung tepat sekali.",hint:"Bagaimana cara memastikan tidak ada yang terlewat DAN tidak ada yang dihitung dua kali?"},
{n:23,type:"mcq",micro:"Strategi bekerja mundur",q:"Strategi 'bekerja mundur' cocok untuk masalah di mana...",options:["Tujuannya belum jelas dan kamu mencari arah untuk memulai","Semua langkahnya acak dan boleh dikerjakan dalam urutan apa saja","Keadaan akhirnya diketahui jelas dan kamu mencari keadaan awal"],answer:2,explain:"Contoh: 'Setelah memberi setengah permen lalu 3 lagi, tersisa 5. Berapa awalnya?' Lebih mudah ditelusuri dari akhir ke awal.",hint:"Kalau kamu tahu tujuannya tapi tidak tahu titik mulainya, arah mana yang lebih mudah?"},
{n:24,type:"mcq",micro:"Strategi menyederhanakan",q:"'Menyederhanakan masalah' berarti...",options:["Sementara memakai angka lebih kecil atau menghilangkan satu syarat, menyelesaikannya, lalu menambahkan kerumitan kembali","Menyerah pada versi yang sulit dan hanya mengerjakan versi mudah saja, lalu menganggap masalahnya sudah selesai","Mengabaikan bagian yang sulit untuk seterusnya dan hanya mengerjakan bagian yang mudah sampai masalahnya dilupakan"],answer:0,explain:"Versi sederhana sering mengungkap struktur atau pola yang lalu bisa diperluas ke versi penuh.",hint:"Selesaikan versi mudahnya dulu untuk memahami caranya."},
{n:25,type:"mcq",micro:"Strategi mencari sub-tujuan",q:"Untuk masalah besar tanpa jalan langsung ke tujuan, strategi 'sub-tujuan' berarti...",options:["Menunggu bantuan orang lain datang dulu sebelum kamu mulai bergerak menuju tujuan","Menetapkan titik-titik antara yang lebih mudah dicapai, lalu bergerak dari satu ke berikutnya","Melupakan tujuan akhir lalu mengerjakan bagian yang paling kamu sukai lebih dulu"],answer:1,explain:"Memecah perjalanan menjadi etape (sub-tujuan) membuat kemajuan terlihat dan tiap langkah lebih terkelola.",hint:"Bagaimana kamu menyeberangi sungai lebar dengan batu loncatan?"},
{n:26,type:"mcq",micro:"Strategi mencari masalah serupa",q:"Sebelum memulai dari nol, pertanyaan strategi yang berguna:",options:["'Apakah masalah ini sulit, sehingga lebih baik langsung dikerjakan orang lain saja?'","'Siapa yang menyuruhku mengerjakan ini, dan apakah ia akan marah jika aku gagal?'","'Pernahkah aku menyelesaikan masalah yang mirip ini? Bagaimana caranya?'"],answer:2,explain:"Banyak masalah baru mirip masalah lama. Mengingat cara sebelumnya menghemat usaha.",hint:"Apakah kamu benar-benar menghadapi sesuatu yang benar-benar baru?"},
{n:27,type:"mcq",micro:"Memilih strategi: pertimbangan",q:"Saat memilih di antara beberapa strategi, hal yang dipertimbangkan:",options:["Mana yang paling cepat menuju jawaban dengan alat dan waktu yang kamu punya, dan yang paling kamu kuasai","Mana yang namanya paling keren dan paling sulit diucapkan, supaya orang lain kagum kepadamu","Mana yang memakan waktu paling lama, karena strategi yang lama hasilnya lebih baik, lebih teliti, dan lebih disukai guru"],answer:0,explain:"Strategi terbaik untuk kamu adalah yang efektif untuk masalah ini DAN bisa kamu jalankan dengan andal.",hint:"Strategi hebat yang tidak bisa kamu jalankan tidak membantu."},
{n:28,type:"mcq",micro:"Ganti strategi saat macet",q:"Kamu sudah 15 menit memakai satu strategi dan tidak ada kemajuan sama sekali. Tindakan bijak:",options:["Paksakan strategi yang sama dengan lebih keras agar segera berhasil","Berhenti, tinjau pemahaman masalah, dan coba strategi berbeda","Menyerah karena satu strategi gagal berarti masalah tak terpecahkan"],answer:1,explain:"Kebuntuan panjang adalah sinyal untuk mengganti pendekatan atau memeriksa apakah kamu salah memahami masalah.",hint:"Kalau satu kunci tidak membuka pintu, apa yang kamu coba?"},
{n:29,type:"mcq",micro:"Kombinasi strategi",q:"Untuk masalah rumit, sering yang terbaik adalah...",options:["Tidak memakai strategi, sebab masalah rumit hanya bisa selesai lewat keberuntungan","Memakai satu strategi dari awal sampai akhir, walau tidak cocok untuk sebagian bagian","Menggabungkan beberapa strategi: gambar diagram untuk memahami, lalu tabel untuk menghitung"],answer:2,explain:"Strategi bisa digabung: satu untuk memahami, satu untuk menghitung, satu untuk memeriksa.",hint:"Apakah kamu harus memilih hanya satu alat untuk seluruh pekerjaan?"},
{n:30,type:"order",micro:"Dari masalah ke pemilihan strategi",q:"Urutkan langkah memilih strategi untuk sebuah masalah.",items:["Pahami masalah: jenis informasinya dan apa yang dicari","Ingat strategi yang kamu tahu dan cocok untuk jenis masalah seperti ini","Pilih satu strategi untuk dicoba lebih dulu","Siapkan untuk beralih ke strategi lain jika yang pertama macet"],answer:[0,1,2,3],explain:"Pahami dulu jenis masalahnya, cocokkan dengan strategi yang kamu kenal, pilih satu, dan bersiap beralih.",hint:"Kamu perlu tahu jenis masalahnya sebelum bisa mencocokkan strategi."},
{n:31,type:"mcq",micro:"Rencana bertingkat",q:"Untuk proyek besar, rencana sering bertingkat: rencana besar (tonggak per bulan) dan rencana rinci (tugas minggu ini). Manfaatnya:",options:["Kamu punya arah jangka panjang sekaligus langkah konkret sekarang, tanpa merencanakan detail bulan depan terlalu dini","Membuat rencana menjadi dua kali lebih panjang tanpa alasan, sehingga terlihat lebih rajin dan lengkap","Membingungkan para anggota karena ada dua rencana yang berbeda, sehingga tiap orang mengerjakan hal yang berlainan, dan hasilnya terpecah"],answer:0,explain:"Rencanakan detail hanya untuk waktu dekat; untuk waktu jauh cukup garis besar, karena keadaan bisa berubah.",hint:"Seberapa rinci sebaiknya kamu merencanakan sesuatu yang masih 2 bulan lagi?"},
{n:32,type:"mcq",micro:"Estimasi dalam rencana",q:"Memberi perkiraan waktu untuk tiap langkah rencana membantu kamu...",options:["Membuat rencana tampak rapi tanpa tahu hasil sebenarnya","Tahu apakah seluruh rencana muat dalam waktu yang tersedia","Membuat rencana terlihat ilmiah dan meyakinkan bagi guru dan teman"],answer:1,explain:"Menjumlahkan perkiraan langkah menunjukkan apakah rencana realistis atau perlu dipangkas.",hint:"Bagaimana kamu tahu rencana 3 jam tidak butuh 8 jam?"},
{n:33,type:"tf",micro:"Rencana pertama jarang sempurna",q:"Benar atau Salah: Rencana pertama yang baik seharusnya tidak perlu diubah sama sekali setelah pelaksanaan dimulai; kalau harus diubah, berarti perencanaannya gagal.",answer:false,explain:"Rencana adalah dugaan terbaik di awal. Menyesuaikannya setelah belajar hal baru saat pelaksanaan adalah tanda pemecah masalah yang baik, bukan kegagalan.",hint:"Apakah nakhoda menyesuaikan arah kapal karena angin, atau menganggapnya gagal?"},
{n:34,type:"mcq",micro:"Strategi 'anggap sudah selesai'",q:"Membayangkan 'masalah sudah terpecah dengan sempurna — seperti apa keadaannya?' membantu karena...",options:["Membuatmu berhenti bekerja karena merasa sudah selesai, padahal belum dikerjakan","Tidak mengubah rencana, karena membayangkan hasil hanyalah kegiatan yang membuang waktu","Memperjelas seperti apa keberhasilan itu, sehingga rencana bisa diarahkan ke sana"],answer:2,explain:"Gambaran jelas tentang 'selesai' menjadi target yang memandu pemilihan langkah.",hint:"Ke mana kamu mengarahkan rencana kalau tidak tahu seperti apa 'sampai tujuan'?"},
{n:35,type:"mcq",micro:"Rencana yang bisa diuji lebih awal",q:"Rencana yang menempatkan 'uji bagian paling tidak pasti' di awal lebih baik daripada di akhir karena...",options:["Kalau ada masalah, masih ada waktu dan tenaga untuk memperbaikinya","Membuat awal pekerjaan terasa berat dan melelahkan bagi tim","Tidak ada bedanya, karena urutan langkah tidak memengaruhi hasil akhir proyek"],answer:0,explain:"Menemukan masalah lebih awal jauh lebih murah daripada menemukannya di malam sebelum tenggat.",hint:"Kapan waktu terbaik menemukan bahwa sesuatu tidak berhasil?"},
{n:36,type:"mcq",micro:"Menyesuaikan strategi dengan batasan",q:"Masalah yang sama bisa butuh strategi berbeda kalau batasannya berubah. Contoh: mencari kata dalam kamus tebal — 'buka acak lalu sesuaikan' vs 'buka tepat di tengah tiap kali'. Yang kedua lebih baik kalau...",options:["Kamu tidak peduli berapa lama waktu pencarian yang dibutuhkan, asalkan akhirnya ketemu","Kamu ingin cara yang terjamin cepat dan sistematis (membagi dua wilayah pencarian tiap langkah)","Kamu suka kejutan dan ingin tahu halaman mana yang akan terbuka pada setiap percobaan"],answer:1,explain:"Strategi 'bagi dua' (pencarian biner) menjamin menemukan kata dengan cepat; 'buka acak' bisa beruntung atau sangat lambat.",hint:"Strategi mana yang selalu memangkas separuh kemungkinan?"},
{n:37,type:"mcq",micro:"Rencana komunikasi",q:"Dalam rencana kelompok, menambahkan 'kapan kita berkumpul untuk mengecek kemajuan' berguna karena...",options:["Membuat rencana terlihat padat sehingga guru mengira kelompokmu rajin","Menambah rapat tak perlu, karena anggota sebaiknya bekerja sendiri","Masalah dan ketidakcocokan antar anggota terdeteksi lebih awal"],answer:2,explain:"Titik pengecekan berkala menjaga semua orang selaras dan menangkap masalah saat masih kecil.",hint:"Bagaimana anggota tahu mereka masih menuju arah yang sama?"},
{n:38,type:"mcq",micro:"Rencana dan prioritas",q:"Kalau waktu tidak cukup untuk semua langkah rencana, cara memilih apa yang tetap dikerjakan:",options:["Kerjakan langkah yang paling penting untuk memenuhi tujuan inti; tunda atau hilangkan yang 'tambahan'","Kerjakan yang paling mudah saja, dan biarkan langkah yang penting untuk tujuan inti tidak tersentuh","Kerjakan semua langkah setengah-setengah supaya semuanya terlihat dimulai, walau tak satu pun tuntas pada akhirnya"],answer:0,explain:"Ketika waktu sempit, lindungi inti (yang benar-benar dibutuhkan tujuan) dan korbankan hiasan.",hint:"Bagian mana yang tanpa itu tujuan tidak tercapai?"},
{n:39,type:"mcq",micro:"Rencana untuk kebiasaan",q:"Untuk tujuan berulang seperti 'PR selesai setiap hari sebelum tidur', rencana terbaik berbentuk...",options:["Tidak perlu rencana, karena kebiasaan akan muncul dengan sendirinya","Rencana rutin/kebiasaan: waktu tetap, tempat tetap, urutan tetap","Rencana baru yang disusun dari nol setiap hari sebelum tidur"],answer:1,explain:"Tujuan berulang paling terbantu oleh rutinitas yang dipikirkan sekali lalu dijalankan otomatis.",hint:"Apakah kamu perlu merencanakan ulang cara menyikat gigi setiap pagi?"},
{n:40,type:"open",micro:"Memilih dan menjelaskan strategi",q:"Masalah: 'Ada 8 tim dalam turnamen sistem gugur (kalah langsung tersingkir). Berapa total pertandingan sampai ada juara?' Pilih sebuah strategi, jelaskan mengapa, dan selesaikan.",explain:"Jawaban baik memilih strategi eksplisit, memberi alasan, menyelesaikan, dan idealnya memeriksa dengan cara kedua.",hint:"Apa yang terjadi pada tepat satu tim setiap pertandingan?",sample:"Strategi: 'pikirkan dari sisi yang kalah'. Setiap pertandingan menyingkirkan tepat 1 tim. Untuk mendapat 1 juara dari 8 tim, 7 tim harus tersingkir. Jadi butuh 7 pertandingan. (Cek dengan cara lain: babak 1 = 4 laga → 4 tim; semifinal = 2 laga → 2 tim; final = 1 laga. 4+2+1 = 7.) Strategi 'hitung yang tersingkir' lebih cepat daripada menggambar seluruh bagan."},
{n:41,type:"mcq",micro:"Komponen rencana lengkap",q:"Rencana yang siap dijalankan biasanya memuat: langkah-langkah, urutan/ketergantungan, penanggung jawab, tenggat tiap langkah, sumber daya, dan...",options:["Daftar hobi anggota","Ramalan bintang","Rencana cadangan untuk langkah berisiko"],answer:2,explain:"Kontinjensi (rencana cadangan) melengkapi rencana: 'kalau langkah X gagal, kita lakukan Y'.",hint:"Apa yang belum ada dari daftar itu yang menangani 'kalau gagal'?"},
{n:42,type:"mcq",micro:"Jalur kritis",q:"'Jalur kritis' sebuah rencana adalah...",options:["Rangkaian langkah bergantung terpanjang yang menentukan waktu tercepat penyelesaian","Langkah yang paling berbahaya dan harus dikerjakan paling akhir oleh tim","Langkah pertama yang menentukan semangat seluruh anggota kelompok proyek"],answer:0,explain:"Menunda langkah mana pun di jalur kritis menunda seluruh proyek. Langkah di luar jalur kritis punya sedikit kelonggaran.",hint:"Rantai mana yang tidak bisa dipercepat dengan menambah orang di tempat lain?"},
{n:43,type:"mcq",micro:"Mempercepat rencana",q:"Untuk menyelesaikan proyek lebih cepat, kamu sebaiknya fokus mempercepat...",options:["Langkah yang paling kamu sukai saja","Langkah-langkah di jalur kritis","Langkah termudah"],answer:1,explain:"Mempercepat langkah di luar jalur kritis tidak memajukan tanggal selesai; hanya jalur kritis yang menentukan.",hint:"Rantai mana yang menentukan total waktu?"},
{n:44,type:"mcq",micro:"Kelonggaran (slack)",q:"Sebuah langkah punya 'kelonggaran' 2 hari artinya...",options:["Langkah itu butuh waktu tepat 2 hari, tidak boleh lebih dan tidak kurang","Langkah itu tidak penting bagi proyek, sehingga boleh dilewati begitu saja","Langkah itu boleh terlambat sampai 2 hari tanpa menunda proyek keseluruhan"],answer:2,explain:"Kelonggaran adalah waktu tunda yang bisa ditoleransi sebuah langkah karena bukan bagian jalur kritis.",hint:"Berapa lama langkah ini boleh molor sebelum jadi masalah?"},
{n:45,type:"mcq",micro:"Kriteria keberhasilan dalam rencana",q:"Menuliskan 'seperti apa hasil yang dianggap berhasil' di awal rencana berguna karena...",options:["Semua orang tahu target yang sama, dan di akhir bisa dinilai apakah tercapai","Membuat rencana jadi lebih panjang dan lebih tebal dari rencana kelompok lain","Hanya formalitas yang harus dipenuhi agar rencana diterima oleh guru"],answer:0,explain:"Kriteria yang jelas mencegah 'selesai' yang berbeda-beda di kepala tiap orang dan memungkinkan evaluasi jujur.",hint:"Bagaimana kalian tahu bersama-sama bahwa pekerjaan sudah cukup baik?"},
{n:46,type:"mcq",micro:"Rencana kontinjensi yang baik",q:"Kontinjensi yang berguna menyebutkan...",options:["Daftar semua kemungkinan buruk yang bisa terjadi di dunia, dari hujan sampai bencana alam besar dan wabah penyakit","Pemicu ('jika hujan pada pukul 15.00') DAN tindakan ('pindah ke aula') DAN siapa yang memutuskan","Hanya kalimat 'semoga tidak hujan' yang ditulis agar anggota tidak cemas memikirkan kegagalan"],answer:1,explain:"Kontinjensi praktis: kondisi pemicu yang jelas, tindakan spesifik, dan orang yang berwenang memutuskan.",hint:"Apa 3 hal yang membuat rencana cadangan bisa langsung dijalankan?"},
{n:47,type:"order",micro:"Menyusun rencana proyek",q:"Urutkan langkah menyusun rencana proyek dari tujuan yang sudah jelas.",items:["Daftar semua langkah/tugas yang dibutuhkan","Tentukan urutan dan ketergantungan antar tugas","Perkirakan waktu & sumber daya tiap tugas, lalu tetapkan penanggung jawab dan tenggat","Kenali jalur kritis dan tambahkan rencana cadangan untuk langkah berisiko"],answer:[0,1,2,3],explain:"Daftar tugas → urutan → estimasi & penugasan → jalur kritis & kontinjensi.",hint:"Kamu perlu daftar tugas sebelum bisa mengurutkannya."},
{n:48,type:"mcq",micro:"Rencana dan asumsi",q:"Menuliskan asumsi rencana ('kami menganggap aula tersedia', 'kami menganggap 50 peserta') berguna karena...",options:["Membuat rencana terdengar pintar dan meyakinkan di mata guru yang membaca dan menilainya","Tidak berpengaruh pada rencana, karena asumsi hanyalah catatan tambahan yang tak dibaca","Kalau sebuah asumsi ternyata salah, kamu langsung tahu bagian rencana mana yang perlu ditinjau"],answer:2,explain:"Asumsi yang eksplisit adalah 'titik pantau': bila berubah, rencana yang bergantung padanya perlu disesuaikan.",hint:"Apa yang kamu anggap pasti benar padahal belum dicek?"},
{n:49,type:"mcq",micro:"Rencana adaptif",q:"Untuk masalah dengan banyak ketidakpastian, pendekatan rencana yang cocok:",options:["Rencanakan langkah kecil berikutnya, laksanakan, pelajari hasilnya, lalu rencanakan langkah berikutnya (iteratif)","Jangan merencanakan apa-apa, karena hal yang belum pasti tidak mungkin direncanakan oleh tim mana pun","Rencanakan detail langkah demi langkah untuk enam bulan ke depan dan jangan diubah walau keadaan berubah total di tengah jalan"],answer:0,explain:"Saat banyak yang tidak diketahui, rencana pendek-berulang (rencanakan sedikit, kerjakan, belajar, ulangi) mengalahkan rencana panjang yang cepat usang.",hint:"Kalau jalannya berkabut, seberapa jauh ke depan kamu bisa merencanakan?"},
{n:50,type:"mcq",micro:"Menyeimbangkan rencana dan tindakan",q:"'Kelumpuhan analisis' terjadi ketika...",options:["Rencanamu terlalu pendek, sehingga kamu cepat selesai lalu kehabisan kegiatan","Kamu terus merencanakan dan menganalisis tanpa pernah mulai bertindak","Kamu bertindak langsung tanpa berpikir, sehingga banyak kesalahan muncul"],answer:1,explain:"Terlalu banyak perencanaan bisa menjadi cara menunda. Pada titik tertentu, langkah kecil memberi informasi lebih baik daripada analisis tambahan.",hint:"Apa lawan dari 'langsung terjun tanpa berpikir'?"},
{n:51,type:"open",micro:"Rencana lengkap dengan jalur kritis",q:"Buat rencana untuk 'pameran karya seni kelas dalam 2 minggu'. Sertakan: minimal 6 tugas, urutan/ketergantungan, perkiraan waktu tiap tugas, jalur kritis, dan 1 kontinjensi.",explain:"Rencana baik: tugas konkret, ketergantungan benar, estimasi, jalur kritis teridentifikasi, dan kontinjensi dengan pemicu + tindakan + pengambil keputusan.",hint:"Cari rantai tugas berurutan terpanjang — itu jalur kritismu.",sample:"Tugas: (1) kumpulkan karya siswa [3 hari, menunggu siswa], (2) seleksi & beri label [1 hari, setelah 1], (3) siapkan ruang & panel [1 hari], (4) pasang karya [1 hari, setelah 2 & 3], (5) buat undangan & publikasi [2 hari, bisa paralel], (6) siapkan buku tamu & pemandu [0,5 hari], (7) gladi & cek pencahayaan [0,5 hari, setelah 4]. Jalur kritis: 1→2→4→7 = 3+1+1+0,5 = 5,5 hari kerja; sisa waktu untuk penyangga. Kontinjensi: jika kurang dari 20 karya terkumpul di hari ke-3 → perpanjang pengumpulan 1 hari dan minta guru seni menghubungi langsung siswa yang belum menyerahkan; keputusan oleh ketua panitia."},
{n:52,type:"mcq",micro:"Rencana yang menyertakan pemeriksaan",q:"Rencana yang baik menaruh langkah 'periksa & perbaiki' ...",options:["Setelah tenggat lewat, ketika semua orang sudah selesai dan tidak sempat memperbaiki lagi","Tidak dimasukkan, sebab memeriksa hanya membuang waktu dan menunda penyerahan tugas kelompok","Sebagai langkah tersendiri sebelum penyerahan/pelaksanaan akhir, bukan hanya berharap semuanya benar"],answer:2,explain:"Menjadwalkan waktu khusus untuk meninjau dan memperbaiki menangkap kesalahan sebelum berdampak.",hint:"Kapan kamu memeriksa PR — sebelum atau sesudah dikumpulkan?"},
{n:53,type:"mcq",micro:"Rencana dan sumber daya bersama",q:"Dua tugas dalam rencana sama-sama butuh satu-satunya proyektor sekolah pada hari Kamis. Rencana yang baik...",options:["Menjadwalkan keduanya di waktu berbeda, atau mencari proyektor tambahan, sebelum konflik terjadi","Membiarkan kedua tim berebut proyektor itu pada hari-H sampai salah satu mengalah","Mengabaikannya karena konflik jadwal akan selesai sendiri saat hari Kamis itu tiba"],answer:0,explain:"Konflik sumber daya bersama harus diselesaikan di tahap perencanaan, bukan saat pelaksanaan.",hint:"Apa yang terjadi kalau dua tim datang mengambil proyektor yang sama?"},
{n:54,type:"mcq",micro:"Rencana yang realistis soal waktu",q:"Orang cenderung terlalu optimis memperkirakan waktu. Cara mengimbanginya dalam rencana:",options:["Jangan pakai perkiraan waktu, karena lamanya pengerjaan tidak mungkin diperkirakan","Tambahkan waktu penyangga, dan/atau kalikan perkiraan awal dengan faktor keamanan","Perkirakan waktu sesingkat mungkin supaya rencana terlihat efisien di mata guru"],answer:1,explain:"Menambahkan penyangga (buffer) mengakui bahwa hambatan tak terduga hampir selalu muncul.",hint:"Kalau kamu selalu meleset optimis, apa yang harus kamu tambahkan?"},
{n:55,type:"mcq",micro:"Strategi untuk masalah baru total",q:"Menghadapi masalah yang benar-benar belum pernah kamu temui, urutan strategi yang masuk akal:",options:["Langsung menebak jawaban akhirnya saja tanpa memahami masalah, mencari analogi, atau mencoba kasus kecil","Mencari orang lain untuk disalahkan karena masalahnya baru dan belum pernah ada penjelasannya di kelas","Pahami sedalam mungkin → cari analogi dengan yang pernah kamu tahu → sederhanakan → coba kasus kecil → cari pola"],answer:2,explain:"Untuk masalah asing, strategi 'memahami + analogi + penyederhanaan + kasus kecil' membuka pintu.",hint:"Apa yang kamu lakukan sebelum mencoba menghitung apa pun?"},
{n:56,type:"mcq",micro:"Rencana sebagai hipotesis",q:"Sikap sehat terhadap rencana yang baru disusun:",options:["Ini dugaan terbaik saat ini; akan diuji oleh kenyataan dan disesuaikan","Ini tidak penting, jadi tidak perlu dibaca lagi setelah selesai disusun","Ini kebenaran mutlak yang tidak boleh diubah oleh anggota mana pun"],answer:0,explain:"Rencana memandu tindakan, tapi kenyataan adalah gurunya. Menyesuaikan berdasarkan hasil nyata adalah bagian dari proses.",hint:"Apakah rencana perjalanan boleh berubah kalau ada jalan ditutup?"},
{n:57,type:"tf",micro:"Strategi salah pilih membuang waktu",q:"Benar atau Salah: Memilih strategi yang tidak cocok untuk sebuah masalah bisa membuatmu bekerja keras tapi tidak maju.",answer:true,explain:"Contoh: memakai 'tebak dan periksa' untuk masalah yang butuh daftar sistematis bisa membuatmu berputar-putar. Mengenali kecocokan strategi menghemat usaha.",hint:"Apakah usaha keras dengan alat yang salah pasti membawa hasil?"},
{n:58,type:"mcq",micro:"Rencana yang bisa dilacak",q:"Agar kemajuan rencana bisa dipantau, tiap langkah sebaiknya punya...",options:["Warna yang berbeda supaya tampilan daftarnya lebih menarik dan berwarna-warni","Definisi 'selesai' yang jelas sehingga bisa dicentang tanpa perdebatan","Nama yang panjang supaya orang yang membacanya langsung paham maksudnya"],answer:1,explain:"Langkah dengan kriteria selesai yang jelas ('undangan tercetak 100 lembar') bisa dilacak; langkah kabur ('kerjakan undangan') tidak.",hint:"Kapan tepatnya sebuah langkah bisa dicoret dari daftar?"},
{n:59,type:"mcq",micro:"Rencana dan pembelajaran",q:"Setelah proyek selesai, membandingkan rencana dengan yang benar-benar terjadi berguna untuk...",options:["Menyalahkan anggota yang dulu salah memperkirakan waktu kerja","Membuktikan bahwa membuat rencana itu sebenarnya tidak berguna bagi tim kecil","Memperbaiki perkiraan dan pilihan strategi di proyek berikutnya"],answer:2,explain:"Retrospektif ('apa yang meleset, mengapa, apa yang akan kita ubah') membangun kemampuan merencanakan dari waktu ke waktu.",hint:"Bagaimana rencana berikutnya jadi lebih baik?"},
{n:60,type:"open",micro:"Merevisi rencana yang macet",q:"Rencana pentas kelas: latihan mestinya selesai hari ke-7, tapi di hari ke-7 baru separuh adegan yang siap, dan pentas hari ke-10. Tuliskan rencana revisi: apa yang dipangkas/disederhanakan, jadwal baru 3 hari tersisa, dan bagaimana mencegah hal serupa lain kali.",explain:"Jawaban baik: memangkas ke inti, jadwal baru yang muat, dan pelajaran proses (latihan lebih sering, pantau harian, buffer waktu).",hint:"Lindungi bagian inti, korbankan yang 'tambahan', dan padatkan jadwal secara realistis.",sample:"Revisi: (1) Pangkas 2 adegan transisi yang tidak penting untuk cerita → fokus 3 adegan inti. (2) Jadwal: hari ke-8 pagi & sore latihan adegan 2–3; hari ke-9 gladi kotor seluruh alur + perbaikan; hari ke-10 pagi gladi bersih, sore pentas. (3) Tambah latihan gabungan lebih pendek tapi setiap hari sejak awal (bukan menumpuk di akhir); tetapkan pemantau kemajuan harian; buat perkiraan waktu latihan per adegan lebih realistis (× 1,5)."},
{n:61,type:"mcq",micro:"Rencana kaku vs fleksibel",q:"Kelemahan rencana yang sangat kaku dan rinci untuk situasi yang cepat berubah:",options:["Terlalu banyak energi terpakai untuk memperbarui rencana, dan orang ragu menyimpang meski keadaan menuntutnya","Kelemahannya tidak ada, karena rencana yang rinci membuat semua pihak yakin dan keadaan pun terkendali","Rencana kaku justru paling baik, karena hasil akhirnya terjamin dan tak perlu disesuaikan lagi"],answer:0,explain:"Di lingkungan tak menentu, rencana terlalu rinci cepat usang dan bisa menghambat penyesuaian yang perlu.",hint:"Apa yang terjadi pada peta rinci kalau jalanan terus berubah?"},
{n:62,type:"mcq",micro:"Bias optimisme perencanaan",q:"'Kekeliruan perencanaan' (planning fallacy) adalah kecenderungan...",options:["Tidak mau merencanakan karena merasa pekerjaan akan selesai dengan sendirinya","Memperkirakan tugas akan selesai lebih cepat dan lebih mulus daripada kenyataannya","Merencanakan terlalu banyak detail kecil sampai rencana lebih panjang dari pekerjaannya"],answer:1,explain:"Orang sistematis meremehkan waktu dan hambatan. Melihat pengalaman proyek serupa sebelumnya memberi perkiraan lebih jujur.",hint:"Apakah tugas biasanya selesai lebih cepat atau lebih lambat dari perkiraan awal?"},
{n:63,type:"tf",micro:"Rencana mengurangi beban keputusan",q:"Benar atau Salah: Punya rencana tertulis tidak berpengaruh pada beban pikiran saat bekerja, karena kamu tetap harus memutuskan 'apa selanjutnya' setiap saat.",answer:false,explain:"Justru salah satu manfaat rencana adalah keputusan 'apa selanjutnya' sudah dibuat di depan, sehingga energi mental saat pelaksanaan bisa dipakai untuk mengerjakan.",hint:"Lebih melelahkan mengikuti daftar atau memutuskan langkah berikutnya setiap 5 menit?"},
{n:64,type:"mcq",micro:"Ketika tidak merencanakan lebih baik",q:"Untuk masalah yang sangat kecil dan cepat (misalnya 'pensil mana yang kupakai'), merencanakan...",options:["Harus ditulis lengkap dengan jadwal dan tugas","Tetap wajib dilakukan sebelum membuat keputusan","Tidak sepadan; keputusan langsung sudah cukup"],answer:2,explain:"Perencanaan punya biaya (waktu, perhatian). Untuk keputusan sepele dan mudah dibatalkan, langsung bertindak lebih efisien.",hint:"Apakah setiap pilihan kecil layak dibuatkan rencana?"},
{n:65,type:"mcq",micro:"Strategi mahal vs murah untuk dicoba",q:"Di antara dua strategi yang sama menjanjikan, sering lebih baik mencoba dulu yang...",options:["Lebih murah dan cepat untuk diuji, sehingga kalau gagal kamu tidak rugi banyak","Lebih mahal dan rumit, supaya kamu terlihat serius menekuni masalahnya","Lebih rumit, karena strategi sulit biasanya menghasilkan jawaban lebih baik dan lebih meyakinkan"],answer:0,explain:"Saat tidak yakin, mulai dengan taruhan kecil: uji strategi yang murah/cepat, dan naikkan komitmen setelah ada bukti berhasil.",hint:"Strategi mana yang lebih sedikit ruginya kalau ternyata tidak jalan?"},
{n:66,type:"tf",micro:"Rencana bersama butuh kesepakatan",q:"Benar atau Salah: Sebuah rencana kelompok bisa 'sempurna' di atas kertas tetapi gagal jika anggota tidak benar-benar memahami dan menyetujuinya.",answer:true,explain:"Rencana hanya berjalan bila dijalankan orang. Kesepakatan dan pemahaman bersama sama pentingnya dengan isi rencananya.",hint:"Apa gunanya rencana bagus yang tidak diikuti siapa pun?"},
{n:67,type:"mcq",micro:"Menahan godaan mengganti strategi terlalu cepat",q:"Kamu baru 3 menit mencoba sebuah strategi lalu tergoda beralih. Pertimbangan sebelum beralih:",options:["Jangan beralih strategi dalam keadaan bagaimanapun juga, karena beralih berarti kamu sudah kalah dari masalah","Apakah aku sudah memberi strategi ini kesempatan yang cukup, atau aku beralih hanya karena belum langsung berhasil?","Segera beralih, karena strategi yang belum berhasil dalam beberapa menit berarti strategi yang buruk"],answer:1,explain:"Ada keseimbangan: bertahan cukup lama untuk strategi bekerja, tapi tidak sampai membuang waktu pada pendekatan yang jelas macet.",hint:"Apakah 3 menit cukup untuk menilai sebuah strategi benar-benar tidak jalan?"},
{n:68,type:"mcq",micro:"Rencana yang mengorbankan pembelajaran",q:"Selalu memilih strategi yang paling kamu kuasai, tidak pernah mencoba yang baru, berisiko...",options:["Tidak ada risiko, karena strategi yang sudah kamu kuasai cocok dipakai untuk masalah jenis apa saja","Kamu jadi terlalu pintar sehingga masalah baru terasa membosankan dan terlalu mudah dikerjakan","Kamu tidak pernah menambah strategi baru ke 'kotak alat', sehingga terjebak saat masalah lama tidak lagi cocok"],answer:2,explain:"Untuk masalah taruhan rendah, mencoba strategi baru adalah investasi: memperluas kemampuanmu untuk masalah sulit di masa depan.",hint:"Bagaimana kamu menambah alat baru kalau selalu memakai alat yang sama?"},
{n:69,type:"mcq",micro:"Rencana dan hal di luar kendali",q:"Rencana yang bergantung pada hal di luar kendalimu (cuaca, keputusan orang lain) sebaiknya...",options:["Punya kontinjensi jelas dan, bila mungkin, dirancang ulang agar lebih sedikit bergantung pada faktor tak terkendali","Dibatalkan, lalu diganti rencana yang hanya dikerjakan sendiri tanpa melibatkan pihak lain mana pun juga","Diabaikan risikonya, karena hal di luar kendali memang tidak perlu dipikirkan dalam rencana kelompok"],answer:0,explain:"Kurangi ketergantungan pada faktor tak terkendali bila bisa; untuk yang tersisa, siapkan rencana cadangan.",hint:"Apa yang bisa kamu ubah supaya rencana tidak runtuh gara-gara satu hal di luar kendali?"},
{n:70,type:"order",micro:"Meninjau rencana sebelum melaksanakan",q:"Urutkan pertanyaan pemeriksa untuk sebuah rencana sebelum dijalankan.",items:["Apakah langkah-langkah ini benar-benar mencapai tujuan (dan kriteria keberhasilan)?","Apakah urutan dan ketergantungannya benar?","Apakah waktu & sumber daya total realistis?","Apa yang paling mungkin gagal, dan apa rencana cadangannya?"],answer:[0,1,2,3],explain:"Cek tujuan → cek urutan → cek kelayakan sumber daya → cek risiko & kontinjensi.",hint:"Mulai dari yang paling mendasar: apakah ini akan mencapai tujuan?"},
{n:71,type:"mcq",micro:"Rencana yang terlalu bergantung pada satu orang",q:"Semua langkah kunci dalam rencana kelompok ditugaskan ke satu anggota paling rajin. Risikonya:",options:["Rencana jadi lebih adil bagi tiap anggota, sebab yang rajin akan mengerjakan semuanya dengan baik","Kalau anggota itu sakit atau kewalahan, seluruh rencana berhenti (titik kegagalan tunggal)","Tidak berisiko, karena anggota yang rajin kebal terhadap sakit dan kewalahan mengerjakan"],answer:1,explain:"Menyebar tanggung jawab kunci mengurangi risiko keseluruhan rencana runtuh karena satu orang.",hint:"Apa yang terjadi kalau satu-satunya orang yang tahu langkah penting tidak masuk?"},
{n:72,type:"mcq",micro:"Strategi 'mundur satu langkah'",q:"Ketika terjebak, strategi 'zoom out' berarti...",options:["Memperbesar tulisan di kertas rencana supaya detailnya lebih jelas dan mudah dibaca oleh seluruh anggota kelompok","Menyerah dan menyerahkan masalahnya kepada orang lain yang dianggap lebih ahli di bidang itu serta lebih berpengalaman","Berhenti mengutak-atik detail, dan bertanya ulang: apa sebenarnya tujuannya, dan adakah pendekatan yang sama sekali berbeda?"],answer:2,explain:"Kadang kebuntuan berasal dari terlalu terpaku pada satu jalan. Melihat gambaran besar bisa memunculkan jalan lain.",hint:"Apa yang kamu lakukan kalau tersesat di dalam labirin — terus jalan, atau mencari peta?"},
{n:73,type:"tf",micro:"Melaksanakan itu sendiri sumber informasi",q:"Benar atau Salah: Mulai melaksanakan langkah pertama sering memberi informasi yang tidak bisa didapat hanya dengan merencanakan lebih lama.",answer:true,explain:"Tindakan nyata mengungkap kendala, kesempatan, dan detail yang tak terlihat dari perencanaan di atas kertas.",hint:"Apa yang kamu pelajari dari benar-benar mencoba memasak, dibanding hanya membaca resep berulang kali?"},
{n:74,type:"mcq",micro:"Rencana vs kenyataan yang berubah drastis",q:"Setengah jalan, keadaan berubah total (tempat acara batal, anggaran dipotong separuh). Respons yang paling matang:",options:["Akui rencana lama tidak lagi cocok, kembali ke 'memahami masalah' dengan keadaan baru, susun rencana baru dari sana","Batalkan segalanya tanpa berpikir panjang, karena rencana yang sudah berubah itu sulit untuk diperbaiki lagi","Paksakan rencana lama tetap berjalan seperti biasa, seolah-olah tempat dan anggarannya tidak berubah"],answer:0,explain:"Perubahan besar pada kondisi berarti sebagian pekerjaan perencanaan harus diulang dengan informasi baru — bukan kegagalan, melainkan penyesuaian.",hint:"Kalau petanya sudah tidak sesuai medan, apa yang kamu lakukan?"},
{n:75,type:"mcq",micro:"Menilai kualitas rencana",q:"Rencana A punya 40 langkah super rinci; Rencana B punya 8 langkah jelas dengan kontinjensi. Untuk proyek 2 minggu oleh 4 siswa, kemungkinan lebih baik:",options:["Keduanya sama baiknya, jadi anggota bebas memilih yang lebih disukai tanpa pertimbangan lain","Rencana B — cukup terarah, mudah diikuti dan disesuaikan, tidak menghabiskan waktu untuk mengurus daftar","Rencana A, karena makin rinci sebuah rencana, makin besar peluang proyeknya berhasil baik"],answer:1,explain:"Kualitas rencana bukan soal jumlah langkah, melainkan apakah ia memberi arah yang cukup tanpa menjadi beban administrasi.",hint:"Apakah 40 langkah membantu 4 siswa, atau membebani mereka?"},
{n:76,type:"mcq",micro:"Rencana dan motivasi",q:"Menyusun rencana agar ada 'kemenangan kecil' di awal (langkah yang cepat selesai dan terlihat hasilnya) membantu karena...",options:["Membuang waktu di awal, sehingga tim terlambat memulai langkah penting","Menunda pekerjaan penting, karena yang dikerjakan hanyalah langkah ringan","Membangun momentum dan keyakinan tim untuk langkah yang lebih berat"],answer:2,explain:"Kemajuan yang terlihat di awal menjaga semangat. Ini pertimbangan manusiawi yang sah dalam menyusun urutan langkah.",hint:"Bagaimana perasaan tim setelah menyelesaikan sesuatu yang nyata di hari pertama?"},
{n:77,type:"tf",micro:"Tidak semua langkah rencana setara pentingnya",q:"Benar atau Salah: Semua langkah dalam sebuah rencana sama pentingnya, jadi saat waktu menipis kamu harus tetap mengerjakan semuanya dengan porsi yang sama.",answer:false,explain:"Biasanya beberapa langkah wajib untuk tujuan inti sementara yang lain hanya 'nilai tambah'. Menandai bedanya sejak awal memudahkan keputusan cepat saat harus memangkas.",hint:"Kalau waktu tinggal separuh, langkah mana yang kamu lindungi?"},
{n:78,type:"mcq",micro:"Strategi dokumentasi ringan",q:"Selama melaksanakan rencana, mencatat singkat 'apa yang berhasil / apa yang menghambat' berguna karena...",options:["Menjadi bahan untuk meninjau dan memperbaiki di akhir, saat ingatan sudah kabur","Membuat pekerjaan menjadi dua kali lipat lebih banyak dan memakan waktu","Tidak ada gunanya, karena ingatan kita sudah cukup untuk mengingat semuanya hingga akhir proyek"],answer:0,explain:"Catatan singkat saat kejadian jauh lebih akurat daripada mengingat-ingat berminggu-minggu kemudian.",hint:"Seberapa jelas kamu mengingat detail masalah proyek dua minggu setelahnya?"},
{n:79,type:"mcq",micro:"Rencana yang mengabaikan pemeliharaan",q:"Rencana 'membuat taman kelas' selesai saat tanaman ditanam, tanpa rencana penyiraman. Kelemahannya:",options:["Menanam saja sudah cukup, sehingga taman itu otomatis terawat dan tujuannya tercapai","Tujuan sebenarnya ('taman yang hidup dan terawat') tidak tercapai; rencana berhenti terlalu cepat","Rencana itu sudah lengkap, karena menanam tanaman adalah tujuan akhir dari sebuah taman"],answer:1,explain:"Rencana harus mencakup seluruh tujuan, termasuk keberlanjutan setelah 'peluncuran'.",hint:"Apakah 'taman selesai dibuat' sama dengan 'taman yang hidup'?"},
{n:80,type:"open",micro:"Menilai dua rencana",q:"Untuk 'mengurangi sampah plastik di kantin dalam sebulan', bandingkan: Rencana A: langsung larang semua plastik mulai besok, sanksi bagi pelanggar. Rencana B: minggu 1 sosialisasi + sediakan alternatif, minggu 2 area percontohan, minggu 3 perluas, minggu 4 evaluasi. Nilai kekuatan dan risiko masing-masing, lalu rekomendasikan.",explain:"Jawaban baik menimbang kecepatan vs keberlanjutan, mengenali pentingnya menyiapkan alternatif dan umpan balik, dan memberi rekomendasi beralasan.",hint:"Pikirkan: apakah perubahan yang dipaksakan tanpa alternatif akan bertahan?",sample:"Rencana A: kekuatan — cepat, tegas. Risiko — penolakan besar karena tidak ada alternatif siap, sulit ditegakkan, bisa gagal total dan merusak dukungan untuk upaya berikutnya. Rencana B: kekuatan — bertahap, menyiapkan alternatif dulu, ada umpan balik tiap minggu, area percontohan mengurangi risiko, evaluasi memungkinkan perbaikan. Risiko — lebih lambat terlihat hasilnya, butuh koordinasi lebih. Rekomendasi: Rencana B, karena perubahan perilaku butuh alternatif dan waktu; tambahkan target terukur mingguan agar kemajuan terlihat."},
{n:81,type:"mcq",micro:"Strategi untuk masalah dengan banyak solusi mungkin",q:"Masalah 'merancang logo klub' punya tak terhingga kemungkinan. Strategi yang membantu menyempit:",options:["Buat satu logo saja dengan cepat, lalu langsung pakai tanpa menilai apakah logo itu cocok atau tidak","Tunggu sampai inspirasi datang sendiri tanpa menetapkan syarat, batasan, atau jumlah sketsa yang harus dibuat","Tetapkan dulu kriteria & batasan (harus terbaca kecil, 2 warna, mencerminkan nama klub), lalu hasilkan 5–10 sketsa, lalu saring"],answer:2,explain:"Untuk masalah desain terbuka: batasi ruang dengan kriteria, hasilkan banyak pilihan, lalu saring dengan kriteria itu.",hint:"Bagaimana kamu memilih di antara tak terhingga pilihan?"},
{n:82,type:"mcq",micro:"Rencana untuk tujuan jangka panjang tak pasti",q:"Tujuan: 'klub coding kelas bisa membuat aplikasi sederhana dalam setahun', padahal anggota belum bisa coding. Pendekatan rencana terbaik:",options:["Tonggak triwulan + rencana rinci hanya untuk triwulan berjalan, ditinjau tiap 3 bulan","Tidak usah direncanakan, sebab anggota yang belum bisa coding akan belajar sendiri nanti","Rencana rinci 12 bulan yang disusun hari ini dan tidak boleh diubah sampai tahun berakhir"],answer:0,explain:"Ketidakpastian tinggi menuntut rencana bertingkat: arah jangka panjang lewat tonggak, detail hanya untuk waktu dekat, tinjau berkala.",hint:"Seberapa akurat kamu bisa merencanakan bulan ke-10 saat keterampilan tim masih akan sangat berubah?"},
{n:83,type:"tf",micro:"Strategi berbeda untuk fase berbeda",q:"Benar atau Salah: Sebuah proyek panjang bisa memakai strategi berbeda di fase berbeda — misalnya 'eksplorasi luas' di awal dan 'fokus & rapikan' menjelang akhir.",answer:true,explain:"Kebutuhan berubah sepanjang proyek: menjelajah banyak ide di awal, lalu menyempit dan menyempurnakan di akhir.",hint:"Apakah cara kerjamu di hari pertama proyek sama dengan di hari terakhir?"},
{n:84,type:"mcq",micro:"Rencana yang menangani ketergantungan eksternal",q:"Rencana pameran bergantung pada izin kepala sekolah yang biasanya lama keluar. Langkah rencana yang bijak:",options:["Anggap saja izinnya keluar tepat waktu, jadi tidak perlu diurus lebih awal dari pekerjaan lain","Ajukan izin sebagai langkah paling awal dan sejajarkan pekerjaan lain yang tidak butuh izin sambil menunggu","Kerjakan semua persiapan dulu, lalu ajukan izin di akhir saat pameran sudah hampir dimulai sebentar lagi, sambil berharap izin cepat"],answer:1,explain:"Item dengan waktu tunggu panjang di luar kendalimu harus dimulai lebih awal, dan pekerjaan lain dijalankan paralel selama menunggu.",hint:"Apa yang harus kamu mulai sekarang justru karena hasilnya lama?"},
{n:85,type:"order",micro:"Menangani proyek yang jauh dari target di tengah jalan",q:"Di pertengahan proyek, kemajuan baru 30% padahal seharusnya 50%. Urutkan langkah respons.",items:["Ukur dengan jujur: berapa yang benar-benar selesai dan berapa sisa waktu","Cari tahu penyebab keterlambatan (estimasi meleset? hambatan tak terduga? kurang orang?)","Sesuaikan: pangkas cakupan ke inti, tambah sumber daya, atau perpanjang tenggat bila mungkin","Susun ulang rencana sisa waktu dan komunikasikan ke semua pihak"],answer:[0,1,2,3],explain:"Ukur → diagnosis penyebab → sesuaikan cakupan/sumber daya/waktu → rencana ulang & komunikasikan.",hint:"Sebelum memutuskan apa yang diubah, ketahui dulu seberapa jauh ketinggalannya dan mengapa."},
{n:86,type:"mcq",micro:"Strategi 'kerjakan yang paling tidak pasti dulu' pada proyek nyata",q:"Tim film pendek tidak yakin apakah bisa meminjam kamera bagus. Menurut strategi mengurangi ketidakpastian, mereka sebaiknya...",options:["Tulis naskah yang sangat detail dulu selama sebulan, lalu urus soal kamera setelahnya","Rekam dengan alat yang ada tanpa mengecek apakah kamera bagus bisa dipinjam atau tidak","Pastikan soal kamera di minggu pertama, karena hampir semua rencana syuting bergantung padanya"],answer:2,explain:"Menyelesaikan ketidakpastian yang mendasari banyak keputusan lain (jenis kamera → gaya syuting → jadwal) harus didahulukan.",hint:"Keputusan mana yang, kalau berubah, akan mengubah banyak bagian rencana lain?"},
{n:87,type:"mcq",micro:"Rencana dengan anggaran waktu ketat",q:"Kamu punya 90 menit untuk mengerjakan 3 tugas: A (wajib, ~50 mnt), B (wajib, ~30 mnt), C (nilai tambah, ~40 mnt). Rencana waktu terbaik:",options:["A lalu B (total 80 mnt), sisakan 10 mnt untuk memeriksa; kerjakan C hanya jika ada waktu lebih","Kerjakan C dulu karena paling menarik, lalu A dan B dikerjakan dengan sisa waktu yang masih ada nanti","Kerjakan ketiganya paralel setengah-setengah, sehingga tak satu pun selesai tepat waktu"],answer:0,explain:"Lindungi yang wajib, sisakan waktu memeriksa, dan perlakukan yang 'nilai tambah' sebagai bonus bila memungkinkan.",hint:"Berapa total waktu yang wajib, dan apakah muat?"},
{n:88,type:"tf",micro:"Rencana bagus tidak menjamin hasil bagus",q:"Benar atau Salah: Jika sebuah rencana dan strategi disusun dengan sangat baik, keberhasilan proyek menjadi terjamin.",answer:false,explain:"Rencana yang baik meningkatkan peluang berhasil dan mempersiapkan kita menghadapi kejutan, tetapi tidak menjamin keberhasilan — selalu ada faktor tak terduga.",hint:"Apakah rencana perjalanan yang matang menjamin tidak ada ban bocor?"},
{n:89,type:"mcq",micro:"Menggabungkan strategi analitis dan kreatif",q:"Untuk masalah 'membuat kegiatan istirahat lebih menyenangkan tanpa biaya', pendekatan yang seimbang:",options:["Hanya fase kreatif: kumpulkan ide sebanyak mungkin lalu langsung jalankan semuanya sekaligus tanpa disaring dengan kriteria yang jelas dan terukur","Fase kreatif: kumpulkan banyak ide liar tanpa menilai; fase analitis: saring dengan kriteria (gratis, aman, muat waktu istirahat, disukai banyak orang)","Hanya fase analitis: tolak semua ide baru yang muncul sejak awal, lalu pakai saja cara lama yang sudah biasa dilakukan oleh sekolah"],answer:1,explain:"Banyak masalah paling baik ditangani dengan bergantian antara menghasilkan ide secara bebas dan menyaringnya secara ketat.",hint:"Kapan menilai ide, dan kapan sebaiknya menahan penilaian?"},
{n:90,type:"mcq",micro:"Rencana yang menyertakan pengukuran",q:"Rencana 'meningkatkan minat baca kelas' yang menyertakan 'catat jumlah buku dipinjam tiap minggu' lebih kuat karena...",options:["Membuat rencana terlihat ilmiah dan canggih, walau hasilnya tidak dipakai menilai usaha","Menambah pekerjaan mencatat tanpa manfaat, sebab angka pinjaman tak terkait minat baca","Kamu bisa tahu apakah usahamu benar-benar berhasil, bukan sekadar merasa berhasil"],answer:2,explain:"Rencana dengan ukuran hasil memungkinkan evaluasi jujur dan penyesuaian berdasarkan bukti, bukan perasaan.",hint:"Bagaimana kamu membuktikan bahwa keadaan membaik?"},
{n:91,type:"mcq",micro:"Rencana untuk masalah yang berulang tiap tahun",q:"Sekolah menghadapi masalah yang sama tiap tahun (kekacauan pendaftaran ekskul). Pendekatan rencana yang paling bernilai jangka panjang:",options:["Selain menangani tahun ini, dokumentasikan proses & masalahnya menjadi panduan/checklist untuk panitia tahun depan","Biarkan panitia berikutnya menemukan sendiri cara mengatasi kekacauan itu, seperti yang dulu dialami panitia sekarang","Tangani keadaan darurat tahun ini saja, lalu lupakan semuanya sampai kekacauan yang sama muncul lagi tahun depan"],answer:0,explain:"Untuk masalah berulang, membangun 'sistem' (panduan, checklist, template) mencegah setiap generasi mengulang kesalahan yang sama.",hint:"Bagaimana agar panitia tahun depan tidak mulai dari nol?"},
{n:92,type:"tf",micro:"Meninjau strategi bagian dari melaksanakan",q:"Benar atau Salah: Setelah strategi dipilih di awal, berhenti di tengah pelaksanaan untuk mempertanyakannya hanya membuang waktu dan sebaiknya dihindari.",answer:false,explain:"Keadaan dan pemahaman berkembang. Sesekali bertanya 'apakah strategi ini masih yang terbaik sekarang?' justru kebiasaan sehat yang mencegah kita bertahan di jalan yang sudah tidak optimal.",hint:"Apakah rute tercepat pagi tadi masih rute tercepat saat terjadi kecelakaan di jalan itu?"},
{n:93,type:"mcq",micro:"Rencana dengan pembagian peran yang jelas",q:"Dalam rencana kelompok, selain 'siapa mengerjakan apa', berguna juga menetapkan...",options:["Warna favorit dan makanan kesukaan tiap orang, supaya suasana kerja lebih akrab","Siapa yang memutuskan bila ada perselisihan, dan siapa yang memantau kemajuan keseluruhan","Siapa yang paling pintar di kelompok, supaya anggota lain tidak perlu ikut berpikir"],answer:1,explain:"Peran koordinasi (pengambil keputusan, pemantau) sama pentingnya dengan peran pelaksana agar rencana tidak macet saat ada konflik.",hint:"Apa yang terjadi kalau dua anggota tidak sepakat dan tidak ada yang berwenang memutuskan?"},
{n:94,type:"open",micro:"Strategi + rencana untuk masalah kompleks",q:"Masalah: 'Nilai matematika sebagian besar kelas rendah pada topik pecahan.' Kamu ketua kelas dan ingin membantu. Buat: (1) strategi umum + alasan, (2) rencana 3 minggu dengan langkah, penanggung jawab, dan ukuran keberhasilan, (3) satu kontinjensi, (4) bagaimana kamu tahu strategi perlu diganti.",explain:"Jawaban baik: strategi beralasan, rencana bertahap dengan PJ dan ukuran hasil, kontinjensi konkret, dan kriteria jelas untuk mengganti strategi.",hint:"Pilih strategi yang memakai sumber daya yang benar-benar kamu punya, dan pasang ukuran hasil sejak awal.",sample:"(1) Strategi: 'teman mengajar teman' + latihan terarah pada kesalahan yang paling umum — karena murah, memakai sumber daya kelas sendiri, dan sesama siswa sering bisa menjelaskan dengan bahasa yang mudah. (2) Minggu 1: kumpulkan 20 soal, identifikasi 3 jenis kesalahan tersering (PJ: 2 siswa + guru); buat 3 lembar latihan pendek. Minggu 2: sesi tutor sebaya 2x (siswa yang kuat memandu kelompok kecil); PR latihan harian 10 menit. Minggu 3: kuis ulang topik yang sama; bandingkan dengan skor awal. Ukuran keberhasilan: rata-rata kuis pecahan naik minimal 15 poin dan jumlah siswa di bawah KKM turun separuh. (3) Kontinjensi: jika tutor sebaya tidak jalan (jadwal bentrok) → ganti dengan video singkat + latihan berpasangan di kelas, diawasi guru. (4) Ganti strategi bila setelah minggu 2 tidak ada perbaikan sama sekali pada latihan harian, atau bila partisipasi di bawah setengah kelas."},
{n:95,type:"mcq",micro:"Rencana dan penyangga",q:"Kamu memperkirakan proyek butuh 10 hari dan tenggatnya 10 hari lagi. Penilaian yang tepat:",options:["Tambah pekerjaan lain supaya waktu 10 hari terpakai penuh dan tidak ada waktu yang tersisa sebelum tenggat","Rencana aman karena perkiraan waktunya pas dengan tenggat, jadi bisa langsung dijalankan tanpa diubah lagi","Rencana berisiko: tidak ada penyangga untuk hambatan tak terduga; sebaiknya pangkas cakupan agar selesai dalam ~8 hari"],answer:2,explain:"Rencana tanpa penyangga hampir selalu meleset karena hambatan tak terduga adalah aturan, bukan pengecualian.",hint:"Apa yang terjadi kalau ada satu hari terganggu?"},
{n:96,type:"mcq",micro:"Strategi menghadapi masalah yang terus berubah",q:"Untuk masalah yang bentuknya terus berubah (misalnya mengelola stan bazar saat ramai), rencana yang cocok:",options:["Beberapa aturan sederhana + peran jelas + titik pengecekan cepat, bukan skrip menit-per-menit","Skrip rinci menit demi menit untuk tiga jam penuh, yang harus diikuti tanpa boleh diubah oleh seluruh petugas stan","Tanpa rencana, sehingga tiap orang berimprovisasi total tanpa peran maupun titik pengecekan"],answer:0,explain:"Situasi dinamis butuh 'kerangka' (aturan, peran, ritme pengecekan) yang memungkinkan penyesuaian cepat, bukan skrip kaku.",hint:"Bisakah skrip menit-per-menit bertahan menghadapi antrean yang tak terduga?"},
{n:97,type:"tf",micro:"Strategi & rencana bisa dipelajari dan ditingkatkan",q:"Benar atau Salah: Kemampuan memilih strategi dan menyusun rencana yang baik berkembang dengan latihan dan meninjau hasil, bukan bakat yang tetap.",answer:true,explain:"Setiap proyek yang kamu rencanakan dan tinjau menambah pengalaman: perkiraan jadi lebih tajam, pilihan strategi lebih tepat.",hint:"Apakah orang menjadi perencana yang lebih baik setelah banyak berlatih?"},
{n:98,type:"mcq",micro:"Menutup proyek dengan benar",q:"Langkah terakhir yang sering terlupa dalam rencana:",options:["Merayakan keberhasilan dengan meriah tanpa memeriksa hasil terhadap kriteria yang ditetapkan","'Tutup' yang rapi: periksa hasil terhadap kriteria, bereskan, ucapkan terima kasih, catat pelajaran","Langsung pindah ke proyek berikutnya tanpa menoleh ke belakang, membereskan, atau mencatat hasilnya"],answer:1,explain:"Penutupan yang baik memastikan tujuan benar-benar tercapai, meninggalkan keadaan rapi, dan menyimpan pelajaran untuk lain kali.",hint:"Apa yang membedakan proyek yang 'ditinggalkan' dari yang 'diselesaikan'?"},
{n:99,type:"mcq",micro:"Ringkasan: strategi dan rencana",q:"Rangkuman paling tepat:",options:["Strategi dan rencana itu artinya sama persis; keduanya sebaiknya disusun sekali di awal, lalu dijalankan secara kaku tanpa perubahan sampai pekerjaan selesai dan ditutup","Strategi hanya berguna untuk soal matematika dan rencana hanya berguna untuk orang dewasa, sehingga anak-anak cukup langsung mengerjakan masalah tanpa persiapan sebelumnya","Strategi memilih pendekatan; rencana menerjemahkannya menjadi langkah nyata dengan urutan, sumber daya, dan cadangan; keduanya dugaan awal yang disesuaikan dengan kenyataan saat dilaksanakan"],answer:2,explain:"Strategi = cara mendekati; rencana = langkah konkret; pelaksanaan = menguji dan menyesuaikan. Ketiganya bekerja bersama.",hint:"Gabungkan: pendekatan → langkah → penyesuaian."},
{n:100,type:"open",micro:"Kapstone: strategi, rencana, laksanakan mental",q:"Pilih satu masalah/tujuan nyata yang akan kamu kerjakan dalam 2–4 minggu. Lakukan seluruh proses: (1) pahami masalah (diketahui/dicari/batasan/kriteria berhasil), (2) pilih 1–2 strategi + alasan, (3) rencana: 6–10 langkah dengan urutan, estimasi waktu, PJ (jika kelompok), (4) identifikasi jalur kritis, (5) 2 kontinjensi, (6) cara memantau kemajuan & kriteria untuk merevisi rencana.",explain:"Kapstone menyatukan: pemahaman masalah, pemilihan strategi beralasan, rencana dengan urutan & estimasi & PJ, jalur kritis, kontinjensi, dan mekanisme pemantauan + revisi.",hint:"Kerjakan keenam bagian berurutan; pastikan tiap langkah punya definisi 'selesai' yang jelas.",sample:"Contoh ringkas — Tujuan: kelas punya sudut baca berisi 30 buku dalam 3 minggu. (1) Diketahui: ada rak kosong, dana Rp150.000, ~15 siswa mau menyumbang buku. Dicari: cara mengisi & menata sudut baca. Batasan: dana, ruang 1,5x1 m, tidak mengganggu jam pelajaran. Berhasil: ≥30 buku tertata berkategori, ada aturan pinjam, ≥60% siswa memakainya dalam 2 minggu pertama. (2) Strategi: gabungan 'sumbangan + tukar' (murah) dan 'sub-tujuan mingguan'. (3) Langkah: kumpulkan buku sumbangan [mgg1, PJ A]; daftar & beli kekurangan buku bekas [mgg1–2, PJ B, Rp150.000]; bersihkan & sampuli [mgg2, PJ C]; buat sistem kategori + label [mgg2, PJ D]; tata rak + papan aturan pinjam [awal mgg3, semua]; sosialisasi + buka [mgg3]; catat peminjaman harian [mgg3–seterusnya, PJ A]. (4) Jalur kritis: kumpulkan buku → beli kekurangan → sampuli → label → tata. (5) Kontinjensi: (a) sumbangan < 20 buku di akhir mgg1 → alihkan lebih banyak dana ke buku bekas + minta bantuan perpustakaan sekolah; (b) dana tidak cukup → prioritaskan buku cerita populer, tunda buku referensi. (6) Pantau: jumlah buku terkumpul tiap akhir minggu vs target (10/20/30); revisi rencana bila di akhir mgg2 total < 20 buku."},
];
